/**
 * Cross-library round-trip tests (WOLS 1.3.0 encrypted format, plus the
 * 1.4.0 string `strain.generation` rule).
 *
 * Runs the shared matrix (tests/interop/matrix.json, a byte-identical copy of
 * the specification's conformance/interop/) through this checkout:
 * - labels generated here decrypt here (self round trip), and this generator
 *   writes `strain.generation` as a string (no case is `legacy`)
 * - the checked-in corpora generated by the published 1.3.0 releases of
 *   `wols` (Python) and `@wemush/wols` decrypt with this checkout, including
 *   their integer `strain.generation`, which must decode as "1"
 * - the verifier rejects corrupted labels, so a passing run means something
 *
 * The live cross-library runs (against `wols` 1.3.0 from PyPI and its `main`
 * branch) are in .github/workflows/interop.yml. See tests/interop/README.md.
 */
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { beforeAll, describe, expect, it } from 'vitest';

import * as wols from '../../src/index.js';

// @ts-expect-error -- plain JavaScript harness shared with specimen-labels-py
import * as harness from './harness.mjs';

interface Result {
  caseId: string;
  status: 'pass' | 'fail' | 'xfail' | 'xpass';
  detail: string;
  legacy: boolean;
}
interface Corpus {
  matrixSha256: string;
  generator: { language: string; version: string };
  cases: Record<string, { url?: string; document?: Record<string, unknown> }>;
}
interface Matrix {
  specimens: Record<string, Record<string, unknown>>;
  cases: {
    id: string;
    form: string;
    kdf: string;
    specimen: string;
    iterations?: number;
    sig?: string;
    specimenId: string;
    legacyPlaintext?: boolean;
  }[];
  expectedFailures?: { case: string; reason: string; reference: string }[];
}

const HERE = dirname(fileURLToPath(import.meta.url));
const MATRIX_PATH = join(HERE, 'matrix.json');
const matrix = harness.loadJson(MATRIX_PATH) as Matrix;
const matrixHash = harness.matrixSha256(MATRIX_PATH) as string;
const corpora = readdirSync(join(HERE, 'corpus'))
  .filter(f => f.endsWith('.json'))
  .sort();

const verify = (corpus: Corpus): Promise<Result[]> =>
  harness.verify(wols, matrix, corpus) as Promise<Result[]>;

async function verifyOne(corpus: Corpus, caseId: string): Promise<Result> {
  const only = { ...matrix, cases: matrix.cases.filter(c => c.id === caseId) };
  const [result] = (await harness.verify(wols, only, corpus)) as Result[];
  return result as Result;
}

describe('interop matrix', () => {
  it('is ASCII-only with unique case ids and documented expected failures', () => {
    expect(readFileSync(MATRIX_PATH).every(byte => byte < 0x80)).toBe(true);
    const ids = matrix.cases.map(c => c.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const entry of matrix.expectedFailures ?? []) {
      expect(ids).toContain(entry.case);
      expect(entry.reason && entry.reference).toBeTruthy();
    }
  });

  it('covers both forms and kdfs, default and minimum iterations, sig, and hostile IDs', () => {
    const forms = new Set(matrix.cases.map(c => `${c.form}/${c.kdf}`));
    expect([...forms].sort()).toEqual(['fields/pbkdf2', 'fields/raw', 'url/pbkdf2', 'url/raw']);
    const pbkdf2 = matrix.cases.filter(c => c.kdf === 'pbkdf2');
    expect(pbkdf2.some(c => c.iterations === undefined)).toBe(true);
    expect(pbkdf2.some(c => c.iterations === 100_000)).toBe(true);
    expect(pbkdf2.some(c => c.iterations === 600_000)).toBe(true);
    expect(matrix.cases.some(c => c.sig !== undefined)).toBe(true);
    const rawSigs = matrix.cases.filter(c => c.kdf === 'raw' && c.sig !== undefined);
    expect(rawSigs.some(c => /[+/=&#? %]/.test(c.sig ?? ''))).toBe(true);
    const ids = matrix.cases.map(c => c.specimenId).join('');
    for (const ch of ['/', '?', '#', '&', '+', '%', ' ']) expect(ids).toContain(ch);
    expect(ids).toContain('%zz');
    expect(/[^\x00-\x7f]/.test(ids)).toBe(true);
  });

  it('covers U+2028, U+2029, </script>, created and a numeric generation', () => {
    const used = new Set(matrix.cases.map(c => c.specimen));
    const docs = JSON.stringify([...used].map(name => matrix.specimens[name]));
    for (const needle of ['\u2028', '\u2029', '</script>', '"created"']) {
      expect(docs).toContain(needle);
    }
    const legacy = matrix.cases.filter(c => c.legacyPlaintext);
    expect(legacy.map(c => c.form).sort()).toEqual(['fields', 'url']);
  });
});

describe('TypeScript self round trip', () => {
  let corpus: Corpus;
  let results: Map<string, Result>;
  beforeAll(async () => {
    corpus = (await harness.generate(wols, matrix, matrixHash, 'checkout')) as Corpus;
    results = new Map((await verify(corpus)).map(r => [r.caseId, r]));
  }, 120_000);

  it.each(matrix.cases.map(c => c.id))('%s', id => {
    const result = results.get(id);
    expect(result?.status === 'pass' || result?.status === 'xfail', result?.detail).toBe(true);
    // WOLS 1.4.0: this generator writes strain.generation as a string.
    expect(result?.legacy, 'generator wrote the legacy (1.3.0) plaintext').toBe(false);
  });

  it('rejects a tampered ciphertext', async () => {
    const entry = corpus.cases['url-raw-full'];
    const [head, tail] = (entry?.url ?? '').split('?e=') as [string, string];
    const flipped = `${head}?e=${tail.startsWith('A') ? 'B' : 'A'}${tail.slice(1)}`;
    const broken = { ...corpus, cases: { ...corpus.cases, 'url-raw-full': { url: flipped } } };
    const result = await verifyOne(broken, 'url-raw-full');
    expect(result.status).toBe('fail');
    expect(result.detail).toContain('authentication-failed');
  });

  it('rejects a dropped sig and an unencoded ID character', async () => {
    const sigUrl = corpus.cases['url-pbkdf2-min-sig-base64url']?.url ?? '';
    const noSig = {
      ...corpus,
      cases: {
        ...corpus.cases,
        'url-pbkdf2-min-sig-base64url': { url: sigUrl.split('&sig=')[0] as string },
      },
    };
    expect((await verifyOne(noSig, 'url-pbkdf2-min-sig-base64url')).detail).toContain('sig');
    const idUrl = corpus.cases['url-raw-id-spec-example']?.url ?? '';
    const plus = {
      ...corpus,
      cases: {
        ...corpus.cases,
        'url-raw-id-spec-example': { url: idUrl.replace('plate%2B3', 'plate+3') },
      },
    };
    expect((await verifyOne(plus, 'url-raw-id-spec-example')).detail).toContain('MUST be encoded');
  });

  it('rejects a leading zero in i, an unknown parameter and a misencoded sig', async () => {
    const mutate = async (caseId: string, fn: (url: string) => string): Promise<Result> => {
      const url = corpus.cases[caseId]?.url ?? '';
      const changed = fn(url);
      expect(changed).not.toBe(url);
      return verifyOne(
        { ...corpus, cases: { ...corpus.cases, [caseId]: { url: changed } } },
        caseId
      );
    };
    const zero = await mutate('url-pbkdf2-min-full', u => u.replace('&i=100000', '&i=0100000'));
    expect(zero.status).toBe('fail');
    expect(zero.detail).toContain('leading zero');
    const extra = await mutate('url-raw-full', u => `${u}&x=1`);
    expect(extra.status).toBe('fail');
    expect(extra.detail).toContain('unknown parameter');
    // A '+' for the encoded space decodes to '+', not ' ' ('+' is literal).
    const plus = await mutate('url-raw-sig-reserved', u => u.replace('g%20h', 'g+h'));
    expect(plus.status).toBe('fail');
    expect(plus.detail).toContain('sig parameter');
    const raw = await mutate('url-raw-sig-reserved', u => u.replace('%C3%A9', '\u00e9'));
    expect(raw.status).toBe('fail');
    expect(raw.detail).toContain('printable ASCII');
  });

  it('rejects field values swapped between fields', async () => {
    const doc = corpus.cases['fields-pbkdf2-min-all']?.document ?? {};
    const swapped = { ...doc, batch: doc['creator'], creator: doc['batch'] };
    const broken = {
      ...corpus,
      cases: { ...corpus.cases, 'fields-pbkdf2-min-all': { document: swapped } },
    };
    const result = await verifyOne(broken, 'fields-pbkdf2-min-all');
    expect(result.status).toBe('fail');
    expect(result.detail).toContain('authentication-failed');
  });
});

describe.each(corpora)('checked-in corpus %s', file => {
  const corpus = harness.loadJson(join(HERE, 'corpus', file)) as Corpus;

  it('was generated from the current matrix', () => {
    expect(corpus.matrixSha256, `regenerate ${file} (see tests/interop/README.md)`).toBe(
      matrixHash
    );
  });

  it('decrypts with this checkout', async () => {
    const failures = (await verify(corpus)).filter(
      r => r.status !== 'pass' && r.status !== 'xfail'
    );
    expect(failures.map(r => `${r.status} ${r.caseId}: ${r.detail}`)).toEqual([]);
  }, 120_000);
});

describe.each(corpora.filter(f => f.endsWith('-1.3.0.json')))('published 1.3.0 corpus %s', file => {
  const corpus = harness.loadJson(join(HERE, 'corpus', file)) as Corpus;
  const legacyCases = matrix.cases.filter(c => c.legacyPlaintext);

  it('carries strain.generation as a JSON integer that decodes as "1"', async () => {
    const only = { ...matrix, cases: legacyCases };
    const results = (await harness.verify(wols, only, corpus)) as Result[];
    expect(results.map(r => [r.caseId, r.status, r.legacy])).toEqual(
      legacyCases.map(c => [c.id, 'pass', true])
    );
  });
});

it('checked-in corpora include a Python-generated one', () => {
  const languages = corpora.map(
    f => (harness.loadJson(join(HERE, 'corpus', f)) as Corpus).generator.language
  );
  expect(languages).toContain('python');
  expect(languages).toContain('typescript');
});
